using System;using System.IO;using System.Linq;using IdleIntelligence.Core;using IdleIntelligence.Runtime;using NUnit.Framework;using UnityEngine;
namespace IdleIntelligence.Tests {[Serializable]public sealed class BalanceReference {public StateData initial;public BalanceReferenceRow[] rows;}
 [Serializable]public sealed class BalanceReferenceRow {public int seconds;public string grant;public BalanceReferenceRun[] runs;}
 [Serializable]public sealed class BalanceReferenceRun {public long run,cycle;public double active,offline;public NumberData credits,data,reward;}
 public sealed class BalanceHistoryTests {
 [Test]public void ThreeProductionAndPrestigeRunsMatchOriginalSourceMeasurements(){var fixture=JsonUtility.FromJson<BalanceReference>(File.ReadAllText(Path.Combine(Application.dataPath,"IdleIntelligence/Tests/EditMode/BalanceHistoryReferenceCases.json")));var s=fixture.initial.ToState();foreach(var row in fixture.rows){s=Game.Buy(s,"calculator");s=Game.Advance(s,s.SavedAt+row.seconds*1000);PrestigeRules.Earn(s,ScientificNumber.Parse(row.grant));s=PrestigeRules.Reset(s);var runs=s.Journal.history.runs;Assert.That(runs.Length,Is.EqualTo(row.runs.Length));for(int i=0;i<runs.Length;i++){var a=runs[i];var e=row.runs[i];Assert.That(a.run,Is.EqualTo(e.run));Assert.That(a.cycle,Is.EqualTo(e.cycle));Assert.That(a.activeSeconds,Is.EqualTo(e.active));Assert.That(a.offlineSeconds,Is.EqualTo(e.offline));Assert.That(ScientificNumber.FromData(a.intReward).CompareTo(ScientificNumber.FromData(e.reward)),Is.Zero,"exact INT reward");foreach(var pair in new[]{new[]{a.credits,e.credits},new[]{a.data,e.data}}){var actual=ScientificNumber.FromData(pair[0]);var expected=ScientificNumber.FromData(pair[1]);if(expected.IsZero)Assert.That(actual.IsZero,Is.True);else Assert.That(actual.Log10(),Is.EqualTo(expected.Log10()).Within(2e-12),"production: JS/Mono pow rounding; exact stored scientific operands retained");}}}}
 [Test]public void NativeCompositeLabelsTranslateAcrossAllSevenLanguages(){Assert.That(UiLocalizedText.Translate("Dr. Mira Voss · Dialogues and chapters","pl"),Is.EqualTo("Dr. Mira Voss · Dialogi i rozdziały"));Assert.That(UiLocalizedText.Translate("Für 20 Gems bestätigen","en"),Is.EqualTo("For 20 Gems confirm"));}

 [Test]public void RealProductionAndRepeatedResetsRemainMeasuredAndBoundedAfterReload(){var s=Game.New(1000000);for(int i=0;i<103;i++){s=Game.Buy(s,"calculator");s=Game.Advance(s,s.SavedAt+1000,true);PrestigeRules.Earn(s,ScientificNumber.Parse("1e20")); // Explicit funded reset fixture, never a natural run.
 var before=s;var next=PrestigeRules.Reset(s);Assert.That(next.Prestige.resets,Is.EqualTo(i+1));Assert.That(next.Journal.history.runs.Last().run,Is.EqualTo(i));Assert.That(next.Journal.history.runs.Last().activeSeconds,Is.EqualTo(1));Assert.That(ScientificNumber.FromData(next.Journal.history.runs.Last().credits).CompareTo(Game.Income(before)),Is.EqualTo(0));s=next;}
 Assert.That(s.Journal.history.runs.Length,Is.EqualTo(JournalCatalog.Runs));Assert.That(s.Journal.history.archivedRuns,Is.EqualTo(3));Assert.That(s.Journal.history.archivedPrestiges,Is.EqualTo(3));var codec=new UnitySaveCodec();var reload=codec.Decode(codec.Encode(StateData.From(s)),AtomicSaveStore.Version).ToState();Assert.That(reload.Journal.history.runs.Length,Is.EqualTo(100));Assert.That(reload.Journal.history.archivedRuns,Is.EqualTo(3));Assert.That(s.Journal.history.runs.All(r=>r.checkpoints.Length<=JournalCatalog.RunCheckpoints));Game.Validate(reload);}
}}
